        rsp[2] = k->do_hw_op(s, IPMI_RESET_CHASSIS, 1);

        break;



    case IPMI_BMC_WATCHDOG_ACTION_POWER_DOWN:

        rsp[2] = k->do_hw_op(s, IPMI_POWEROFF_CHASSIS, 1);

        break;



