        return;

    }



    val = (cmd[3] >> 4) & 0x7; /* Validate preaction */

    switch (val) {

    case IPMI_BMC_WATCHDOG_PRE_MSG_INT:

    case IPMI_BMC_WATCHDOG_PRE_NONE:

        break;



    case IPMI_BMC_WATCHDOG_PRE_NMI:

        if (!k->do_hw_op(s, IPMI_SEND_NMI, 1)) {

            /* NMI not supported. */

            rsp[2] = IPMI_CC_INVALID_DATA_FIELD;

            return;

