        break;



    default:

        /* We don't support PRE_SMI */

        rsp[2] = IPMI_CC_INVALID_DATA_FIELD;

        return;

    }



    ibs->watchdog_initialized = 1;

    ibs->watchdog_use = cmd[2] & IPMI_BMC_WATCHDOG_USE_MASK;

    ibs->watchdog_action = cmd[3] & IPMI_BMC_WATCHDOG_ACTION_MASK;

